function longestUnique(text: string): number {
  const chars = Array.from(text);
  const seen = new Set<string>();
  let left = 0;
  let best = 0;

  for (const char of chars) {
    while (seen.has(char)) {
      seen.delete(chars[left++]);
    }
    seen.add(char);
    best = Math.max(best, seen.size);
  }
  return best;
}

type RecordItem = { id: string; name: string };

function dedupe(items: RecordItem[]): RecordItem[] {
  const seen = new Set<string>();
  return items.filter((item) => {
    if (seen.has(item.id)) return false;
    seen.add(item.id);
    return true;
  });
}

function labelsByLevel(root: Element): string[] {
  const result: string[] = [];
  const queue: Element[] = [root];
  let head = 0;

  while (head < queue.length) {
    const node = queue[head++];
    if (node.matches('[role="menuitem"]')) {
      result.push(node.textContent?.trim() ?? '');
    }
    queue.push(...node.children);
  }
  return result;
}

function memoize<A, R>(fn: (arg: A) => R): (arg: A) => R {
  const cache = new Map<A, R>();
  return (arg) => {
    if (cache.has(arg)) return cache.get(arg)!;
    const value = fn(arg);
    cache.set(arg, value);
    return value;
  };
}

function debounce<T extends (...args: any[]) => void>(fn: T, wait: number) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  const debounced = function (this: unknown, ...args: Parameters<T>) {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), wait);
  };
  debounced.cancel = () => {
    if (timer) clearTimeout(timer);
    timer = undefined;
  };
  return debounced;
}

